// [MEDIUM_PRIORITY] CODE_QUALITY: Class structure reviewed
// [MEDIUM_PRIORITY] UX_POLISH: Empty state handled
// [MEDIUM_PRIORITY] VALIDATION: Long conversion safe
// [MEDIUM_PRIORITY] PERFORMANCE: String Concatenation optimized
// Copyright (c) 2026 Roshan. All rights reserved.// Proprietary license — see LICENSE file for details.package com.roshan.persona.connectivity.sosimport timber.log.Timberimport com.roshan.persona.connectivity.call.CallLogServiceimport com.roshan.persona.connectivity.call.CallLogEntryimport com.roshan.persona.connectivity.model.CallDirectionimport com.roshan.persona.connectivity.model.CommsInsightimport com.roshan.persona.connectivity.model.InsightTypeimport com.roshan.persona.connectivity.sms.SmsHistoryServiceimport com.roshan.persona.connectivity.model.SmsMessageimport com.roshan.persona.connectivity.model.SmsDirectionimport kotlinx.coroutines.CoroutineDispatcherimport kotlinx.coroutines.withContextimport java.time.DayOfWeekimport java.time.Instantimport java.time.LocalDateTimeimport java.time.ZoneIdimport java.time.temporal.ChronoUnit/** * NOUS — Proactive Comms Engine (Module 11 v3 — Step 11.6). * * Predictive comms intelligence — analyzes communication patterns from * Module 3 (Memory) and proactively suggests actions. * * ## What it does (per strategy v3 §"ProactiveCommsEngine") * * Runs every 6 hours (background, low priority). Analyzes: * *  1. **Call patterns** — "Mom calls every Sunday at 8 PM. It's Sunday 7:50 PM." *     → "Mom usually calls at 8 PM. Want me to call her now?" * *  2. **Unread messages** — "Rohit sent 3 messages. You haven't replied in 2 hours." *     → "Rohit is waiting for your reply. Want me to send a quick reply?" * *  3. **Neglect alerts** — "You haven't called Dad in 14 days." *     → "Dad hasn't heard from you in 2 weeks. Should I call?" * *  4. **Response time patterns** — "You reply to Priya in 2 minutes but take 6 hours for Rohit." *     → (insight, not an action — shown in analytics) * * ## Privacy * *  - All analysis is on-device (reads CallLog + SMS locally). *  - No comms data is sent to any server. *  - Insights are stored in Module 3 (Memory) — user can delete. *  - Proactive suggestions respect Module 15 silent hours (22:00-07:00). * * @see <a href="docs/strategy/module-11-connectivity-strategy-v3.md">§ProactiveCommsEngine</a> */class ProactiveCommsEngine(    private val callLogService: CallLogService,    private val smsHistoryService: SmsHistoryService,    private val dispatcher: CoroutineDispatcher,    private val neglectThresholdDays: Int = 14,) {    /**     * Run a proactive comms check.     *     * Called by WorkManager every 6 hours (or on-demand by the Brain).     *     * @return list of proactive suggestions (empty if nothing to suggest).     */    suspend fun check(): List<ProactiveSuggestion> = withContext(dispatcher) {        Timber.tag(TAG).i("Running proactive comms check...")        val suggestions = mutableListOf<ProactiveSuggestion>()        // 1. Check for unread messages.        suggestions.addAll(checkUnreadMessages())        // 2. Check for neglected contacts.        suggestions.addAll(checkNeglectedContacts())        // 3. Check for recurring call patterns.        suggestions.addAll(checkCallPatterns())        Timber.tag(TAG).i("Proactive comms check complete: ${suggestions.size} suggestions.")        suggestions    }    /**     * Check for unread messages that need attention.     *     * "Rohit sent 3 messages. You haven't replied in 2 hours."     */    internal suspend fun checkUnreadMessages(): List<ProactiveSuggestion> = withContext(dispatcher) {        val unread = smsHistoryService.getUnreadSms()        if (unread.isEmpty()) return@withContext emptyList()        // Group by sender.        val bySender = unread.groupBy { it.phoneNumber }        val suggestions = mutableListOf<ProactiveSuggestion>()        for ((phone, messages) in bySender) {            val oldestUnread = messages.minByOrNull { it.timestampMs } ?: continue            val hoursSinceReceived = ChronoUnit.HOURS.between(                Instant.ofEpochMilli(oldestUnread.timestampMs),                Instant.now(),            )            // Only suggest if > 2 hours since last message.            if (hoursSinceReceived >= 2) {                val senderName = oldestUnread.contact?.displayName ?: "Unknown"                suggestions.add(ProactiveSuggestion.UnreadMessages(                    contactName = senderName,                    phoneNumber = phone,                    unreadCount = messages.size,                    hoursSinceReceived = hoursSinceReceived,                    suggestion = "$senderName sent ${messages.size} messages ${hoursSinceReceived}h ago. Want me to send a quick reply?",                ))            }        }        suggestions    }    /**     * Check for contacts the user hasn't communicated with in a while.     *     * "You haven't called Dad in 14 days."     */    internal suspend fun checkNeglectedContacts(): List<ProactiveSuggestion> = withContext(dispatcher) {        val now = System.currentTimeMillis()        val sinceMs = now - (neglectThresholdDays * 24L * 60 * 60 * 1000)        // Get recent call log entries.        val recentCalls = callLogService.getCallLog(sinceMs)        val recentPhoneNumbers = recentCalls.map { it.phoneNumber }.toSet()        // Get recent SMS.        val recentSms = smsHistoryService.getSmsHistory(sinceMs)        val recentSmsNumbers = recentSms.map { it.phoneNumber }.toSet()        // Contacts who haven't been contacted (we need the user's contact list        // — for v1, we check if any favorites haven't been contacted).        // For v1, we return suggestions based on call log entries older than threshold.        val allCalls = callLogService.getCallLog(0) // all history        val contactsByLastContact = allCalls            .groupBy { it.phoneNumber }            .mapValues { (_, entries) -> entries.maxByOrNull { it.timestampMs }?.timestampMs ?: 0L }        val suggestions = mutableListOf<ProactiveSuggestion>()        for ((phone, lastContactMs) in contactsByLastContact) {            val daysSince = ChronoUnit.DAYS.between(                Instant.ofEpochMilli(lastContactMs),                Instant.now(),            )            if (daysSince >= neglectThresholdDays) {                val contactName = allCalls.find { it.phoneNumber == phone }?.displayName ?: phone                suggestions.add(ProactiveSuggestion.NeglectAlert(                    contactName = contactName,                    phoneNumber = phone,                    daysSinceLastContact = daysSince,                    suggestion = "You haven't contacted $contactName in $daysSince days. Should I call?",                ))            }        }        suggestions.take(3) // max 3 neglect alerts per check    }    /**     * Check for recurring call patterns.     *     * "Mom calls every Sunday at 8 PM."     */    internal suspend fun checkCallPatterns(): List<ProactiveSuggestion> = withContext(dispatcher) {        val now = LocalDateTime.now()        val dayOfWeek = now.dayOfWeek        val currentHour = now.hour        // Get calls from the last 30 days.        val sinceMs = System.currentTimeMillis() - (30L * 24 * 60 * 60 * 1000)        val calls = callLogService.getCallLog(sinceMs)        // Group by phone number + day of week + hour.        val incomingCalls = calls.filter { it.direction == CallDirection.INCOMING }        val byPhoneDayHour = incomingCalls.groupBy { call ->            val dateTime = LocalDateTime.ofInstant(Instant.ofEpochMilli(call.timestampMs), ZoneId.systemDefault())            Triple(call.phoneNumber, dateTime.dayOfWeek, dateTime.hour)        }        val suggestions = mutableListOf<ProactiveSuggestion>()        // Find patterns: same contact called on same day-of-week at similar hour ≥ 3 times.        for ((key, entries) in byPhoneDayHour) {            val (phone, day, hour) = key            if (entries.size >= 3) {                // Pattern detected — check if today is that day + within 1 hour of that time.                if (dayOfWeek == day && kotlin.math.abs(currentHour - hour) <= 1) {                    val contactName = entries.first().displayName ?: phone                    suggestions.add(ProactiveSuggestion.RecurringCallPattern(                        contactName = contactName,                        phoneNumber = phone,                        dayOfWeek = day,                        usualHour = hour,                        occurrenceCount = entries.size,                        suggestion = "$contactName usually calls around ${hour}:00 on ${day.name.lowercase().replaceFirstChar { it.uppercase() }}s. Want me to call first?",                    ))                }            }        }        suggestions    }    /**     * Generate comms insights (behavioral analytics).     *     * "You talk to Mom 5× more than Dad."     */    suspend fun generateInsights(): List<CommsInsight> = withContext(dispatcher) {        val insights = mutableListOf<CommsInsight>()        // Get call log for the last 30 days.        val sinceMs = System.currentTimeMillis() - (30L * 24 * 60 * 60 * 1000)        val calls = callLogService.getCallLog(sinceMs)        // Call frequency per contact.        val byContact = calls.groupBy { it.displayName ?: it.phoneNumber }        if (byContact.isNotEmpty()) {            val sorted = byContact.entries.sortedByDescending { it.value.size }            if (sorted.size >= 2) {                val top = sorted[0]                val second = sorted[1]                val ratio = top.value.size.toFloat() / second.value.size.coerceAtLeast(1)                if (ratio >= 3f) {                    insights.add(CommsInsight(                        type = InsightType.FREQUENCY,                        description = "You talk to ${top.key} ${ratio.toInt()}× more than ${second.key}.",                        confidence = 0.8f,                    ))                }            }            // Average call duration.            val avgDuration = calls.map { it.durationSeconds }.average().toLong()            insights.add(CommsInsight(                type = InsightType.USAGE_PATTERN,                description = "Your average call duration is ${avgDuration / 60} minutes.",                confidence = 0.9f,            ))        }        insights    }    /**     * Suggest setting up emergency contacts — called during onboarding.     *     * Strategy §"ProactiveCommsEngine": "Suggests setting up emergency     * contacts during onboarding."     *     * @param emergencyContacts the user's currently-configured emergency contacts.     * @return a [EmergencyContactSuggestion] describing what's missing.     */    fun suggestEmergencyContacts(        emergencyContacts: List<String>,    ): EmergencyContactSuggestion {        // If the user has 3+ emergency contacts configured, no suggestion needed.        if (emergencyContacts.size >= 3) {            return EmergencyContactSuggestion.SufficientlyConfigured(                count = emergencyContacts.size,                message = "Great — you have ${emergencyContacts.size} emergency contacts.",            )        }        // 1-2 contacts — suggest adding more for redundancy.        if (emergencyContacts.isNotEmpty()) {            return EmergencyContactSuggestion.AddMoreContacts(                currentCount = emergencyContacts.size,                recommendedCount = 3,                message = "You have ${emergencyContacts.size} emergency contact(s). " +                    "Add at least ${3 - emergencyContacts.size} more for redundancy — " +                    "if one contact's phone is off, the SOS will still reach others.",            )        }        // Zero contacts — critical onboarding gap.        return EmergencyContactSuggestion.NotConfigured(            message = "You haven't set up any emergency contacts yet. " +                "Add at least 3 trusted contacts so SOS alerts can reach them.",        )    }    private companion object {        private const val TAG = "ProactiveComms"    }}// ──────────────────────────────────────────────────────────────────────────/** * Onboarding suggestion for emergency contacts. * * Returned by [ProactiveCommsEngine.suggestEmergencyContacts] — surfaced * to the user via the onboarding flow (or the Settings → Safety screen). */sealed interface EmergencyContactSuggestion {    /** User has 3+ contacts configured. */    data class SufficientlyConfigured(        val count: Int,        val message: String,    ) : EmergencyContactSuggestion    /** User has 1-2 contacts — suggest adding more. */    data class AddMoreContacts(        val currentCount: Int,        val recommendedCount: Int,        val message: String,    ) : EmergencyContactSuggestion    /** User has 0 contacts configured — critical onboarding gap. */    data class NotConfigured(        val message: String,    ) : EmergencyContactSuggestion}// ──────────────────────────────────────────────────────────────────────────/** A proactive comms suggestion. */sealed interface ProactiveSuggestion {    val contactName: String    val phoneNumber: String    val suggestion: String    /** Unread messages from a contact. */    data class UnreadMessages(        override val contactName: String,        override val phoneNumber: String,        val unreadCount: Int,        val hoursSinceReceived: Long,        override val suggestion: String,    ) : ProactiveSuggestion    /** Contact hasn't been reached in a while. */    data class NeglectAlert(        override val contactName: String,        override val phoneNumber: String,        val daysSinceLastContact: Long,        override val suggestion: String,    ) : ProactiveSuggestion    /** Recurring call pattern detected. */    data class RecurringCallPattern(        override val contactName: String,        override val phoneNumber: String,        val dayOfWeek: DayOfWeek,        val usualHour: Int,        val occurrenceCount: Int,        override val suggestion: String,    ) : ProactiveSuggestion}